-- Marketplace refresh from the November 2026 product research (content/product-research.md):
-- lead with property developers and shortlets, narrow clinics, pause school admissions and logistics.
INSERT OR IGNORE INTO products (id,slug,name,category,industry,tagline,description,features_json,includes_json,demo_url,accent,price_ngn_setup,price_ngn_monthly,price_usd_setup,price_usd_monthly,buyout_ngn,buyout_usd,delivery_days,sort,updated_by) VALUES
('p_developer_portal','developer-sales-portal','Developer Sales & Subscriber Portal','webapp','Real estate','Instalment tracking, receipts and site-progress updates for property developers and their diaspora buyers.','For developers selling plots and units on instalment plans. Every buyer gets a portal with their payment schedule, receipts and site-progress photos; your team gets one dashboard for leads, instalments and overdue reminders, with WhatsApp updates going out automatically. Built for Lagos, Abuja and Port Harcourt developers selling to buyers at home and abroad.','["Buyer portal: payment schedule, receipts, documents", "Instalment ledger with a dedicated Paystack account per buyer", "Overdue reminders by WhatsApp and email", "Site-progress updates with photos", "Lead desk for WhatsApp and website enquiries", "Card payments for diaspora buyers"]','["Set-up with your estates, plots and price lists", "Dashboard for up to 5 staff", "Hosting, SSL, backups and updates"]',NULL,'#b4532a',850000,150000,750,149,NULL,NULL,35,5,'research'),
('p_shortlet_desk','shortlet-booking-desk','Shortlet Direct-Booking Desk','webapp','Hospitality','Your own booking site for shortlet apartments: live availability, Paystack payments, caution fees and WhatsApp check-in.','Take bookings without handing a slice of every stay to a platform. Guests see live availability, pay securely with Paystack, upload ID and get check-in instructions on WhatsApp automatically. Your calendar stays in sync with Airbnb and Booking.com so you never double-book.','["Booking site with live availability and photos", "Paystack payments plus caution-fee handling", "Guest ID upload before check-in", "Calendar sync with Airbnb and Booking.com", "Automatic WhatsApp check-in and check-out messages", "Owner dashboard across all units"]','["Set-up for up to 10 units", "Custom domain and hosting", "Monthly care and updates"]',NULL,'#0f766e',250000,50000,250,49,NULL,NULL,21,6,'research');

UPDATE products SET
  tagline = 'Bookings, deposits and WhatsApp reminders for dental, eye, fertility and physio clinics and labs.',
  description = 'A front desk that runs itself for specialist clinics and diagnostic labs: patients book a service and time online, pay a deposit if you want one, and get WhatsApp reminders and "your result is ready" messages automatically. Your staff confirm and manage the day from one dashboard. It is a booking and communication system, not a medical-records system.',
  features_json = '["Online booking by service, specialist and branch", "Optional booking deposits with Paystack", "WhatsApp reminders the day before", "“Result ready” notifications for labs", "Front-desk dashboard with today’s queue", "AI assistant for opening hours, prices and directions"]',
  price_ngn_setup = 350000, price_ngn_monthly = 85000, price_usd_setup = 600, price_usd_monthly = 99, sort = 10, updated_by = 'research', updated_at = datetime('now')
WHERE slug = 'clinic-front-desk';

UPDATE products SET published = 0, updated_by = 'research', updated_at = datetime('now')
WHERE slug IN ('school-admissions-portal', 'logistics-quote-track');

UPDATE knowledge SET content = 'Ready-built products with live demos: Clinic Front Desk (for dental, eye, fertility and physio clinics and labs), Clinic/School/Real Estate/Logistics websites, AI Website Assistant, WhatsApp Appointment Reminders, Lead Follow-up Autopilot. Early access (founding clients, no demo yet): Developer Sales & Subscriber Portal for property developers, Shortlet Direct-Booking Desk for shortlet apartments. Plans: Launch (deployed for you), Managed (hosted and maintained monthly), Own the code (buyout licence).', updated_by = 'research'
WHERE id = 'k_marketplace';
